INSERT IGNORE INTO glossaries (term, rule_text, note) VALUES
    ('EOD', '해당 근무일의 업무 종료 시점까지라는 의미로 해석한다.', 'End of Day. 종료 시각은 회사와 시간대에 따라 다를 수 있으므로 중요한 기한은 구체적인 시각과 시간대를 확인한다.'),
    ('COB', '해당 사업장의 영업 또는 업무 종료 시점까지라는 의미로 해석한다.', 'Close of Business. EOD와 비슷하게 쓰이지만 지역과 조직의 영업시간에 따라 기준이 달라질 수 있다.'),
    ('ASAP', '가능한 한 빠르게 처리해 달라는 요청으로 해석하되 고정된 마감 시각으로 단정하지 않는다.', 'As Soon As Possible. 우선순위와 기대 완료 시각이 모호할 수 있으므로 필요한 경우 구체적인 기한을 확인한다.'),
    ('FYI', '참고를 위해 공유하는 정보로 해석하며 별도 요청이 없다면 즉각적인 조치가 필수라고 단정하지 않는다.', 'For Your Information. 정보 공유가 기본 의미지만 문맥에 따라 검토나 후속 대응을 기대할 수 있다.'),
    ('TBD', '세부 내용이나 결정이 아직 확정되지 않은 상태로 해석한다.', 'To Be Determined. 담당자, 일정 또는 범위가 추후 결정될 예정임을 나타낸다.'),
    ('TBA', '확정된 내용을 추후 공지하거나 아직 공개되지 않은 상태로 해석한다.', 'To Be Announced. 조직에 따라 미정이라는 의미로도 느슨하게 사용되므로 문맥을 확인한다.'),
    ('ETA', '도착 또는 작업 완료가 예상되는 시점을 의미하는 표현으로 해석한다.', 'Estimated Time of Arrival. 물류에서는 도착 시각, 프로젝트에서는 예상 완료 시각으로 사용될 수 있다.'),
    ('OOO', '부재 중이어서 통상적인 업무 응답이 어려운 상태로 해석한다.', 'Out of Office. 휴가, 출장, 병가 등 부재 사유와 복귀 시점은 별도 안내를 확인한다.'),
    ('PTO', '회사의 유급 휴가 또는 유급 비근무 시간을 의미하는 표현으로 해석한다.', 'Paid Time Off. 포함되는 휴가 유형과 운영 방식은 국가 및 회사 정책에 따라 다를 수 있다.'),
    ('KPI', '성과를 측정하기 위해 정한 핵심 지표로 해석한다.', 'Key Performance Indicator. 조직이나 업무 단위별로 목표 수치와 측정 방식이 다르게 정의된다.'),
    ('OKR', '목표와 그 달성도를 확인할 핵심 결과를 함께 관리하는 방식으로 해석한다.', 'Objectives and Key Results. 운영 주기와 평가 반영 방식은 조직마다 다를 수 있다.'),
    ('R&R', '업무 문맥에서는 구성원이나 조직의 역할과 책임 범위를 의미하는 표현으로 우선 해석한다.', 'Roles and Responsibilities. 다른 의미로 쓰일 수도 있으므로 조직 및 문장 문맥을 함께 확인한다.'),
    ('WIP', '아직 완료되지 않고 진행 중인 작업 또는 산출물로 해석한다.', 'Work in Progress. 검토 가능한 초안인지 단순 진행 상태인지 문맥에 따라 확인한다.'),
    ('POC', '문맥에 따라 개념 검증 또는 담당 연락 창구를 의미하는 약어로 해석한다.', 'Proof of Concept 또는 Point of Contact. 개발 검증과 담당자 지정 중 어느 의미인지 반드시 문맥으로 구분한다.'),
    ('ROI', '투입 비용 대비 얻는 수익이나 효과를 평가하는 지표로 해석한다.', 'Return on Investment. 금전적 수익 외에 시간 절감이나 전략적 효과를 포함하는지는 조직 기준을 확인한다.'),
    ('B2B', '기업이 다른 기업을 대상으로 제품이나 서비스를 제공하는 사업 관계로 해석한다.', 'Business to Business. 고객, 계약, 영업 주체가 기업인 거래 모델을 가리킨다.'),
    ('B2C', '기업이 개인 소비자를 대상으로 제품이나 서비스를 제공하는 사업 관계로 해석한다.', 'Business to Consumer. 최종 소비자를 직접 고객으로 삼는 거래 모델을 가리킨다.'),
    ('품의', '조직 내부에서 안건을 상신하고 검토 및 승인을 요청하는 절차로 해석한다.', '한국 기업에서 비용 집행이나 의사결정 등을 위해 승인권자에게 안건을 올리는 내부 절차를 뜻한다.'),
    ('결재', '권한을 가진 사람이 업무 안건을 검토하고 승인하거나 반려하는 행위로 해석한다.', '조직 내부 승인 절차를 뜻하며 대금을 지불하는 결제와 구분한다.'),
    ('회람', '문서나 정보를 여러 관계자에게 순서대로 또는 동시에 공유해 열람하게 하는 절차로 해석한다.', '수신자가 단순 열람만 하는지 의견 제출이나 확인 표시가 필요한지는 별도 요청을 확인한다.'),
    ('유관부서', '현재 안건과 업무상 관련되거나 영향을 주고받는 부서로 해석한다.', '직접 담당 부서뿐 아니라 검토, 협조 또는 승인에 참여하는 조직을 포함할 수 있다.'),
    ('실무진', '업무를 직접 수행하고 세부 실행을 담당하는 구성원 또는 담당 그룹으로 해석한다.', '의사결정권자와 구분해 쓰이기도 하지만 책임 범위는 조직 구조에 따라 다를 수 있다.'),
    ('컨펌', '내용을 확인하고 동의 또는 승인을 받는 행위로 해석한다.', '단순 사실 확인과 공식 승인 모두에 사용될 수 있으므로 필요한 승인 수준을 문맥에서 구분한다.'),
    ('팔로업', '이전 논의나 요청 이후의 진행 상황을 확인하고 필요한 후속 조치를 수행하는 것으로 해석한다.', 'Follow-up. 상태 확인, 재요청, 결과 공유 등 구체적인 다음 행동은 문맥에 따라 달라진다.'),
    ('얼라인', '관계자 사이의 목표, 이해 또는 실행 방향을 일치시키는 조율 과정으로 해석한다.', 'Align. 완전한 합의인지 단순 정보 공유인지 문맥에 따라 기대 수준을 확인한다.'),
    ('액션 아이템', '회의나 논의 결과로 담당자와 완료 기준이 필요한 구체적인 후속 작업으로 해석한다.', 'Action item. 가능하면 담당자, 기한 및 완료 조건과 함께 명시한다.'),
    ('블로커', '작업 진행이나 완료를 막고 있어 우선 해결이 필요한 장애 요인으로 해석한다.', 'Blocker. 기술 문제, 의사결정 지연, 외부 의존성 등 원인과 해결 담당자를 함께 확인한다.'),
    ('핸드오프', '업무의 책임, 진행 정보 또는 산출물을 다음 담당자나 팀에 인계하는 과정으로 해석한다.', 'Handoff. 누락을 방지하려면 현재 상태, 남은 작업, 관련 자료와 담당자를 함께 전달한다.'),
    ('네마와시', '공식 결정 전에 이해관계자와 사전 조율하고 합의 기반을 만드는 과정으로 해석한다.', '일본 조직문화의 관행으로, 공식 회의나 결정 전에 관계자들과 비공식적으로 의견을 조율하는 방식을 가리킨다.'),
    ('링기', '문서화된 안건을 관련 승인자에게 회람해 순차적으로 검토와 승인을 받는 절차로 해석한다.', '일본 조직의 린기 또는 품의 관행을 가리키며 구체적인 승인 단계와 권한은 조직마다 다를 수 있다.'),
    ('PR', '개발 문맥에서는 코드 변경을 검토하고 병합하기 위한 Pull Request로 해석한다.', 'Pull Request. 개발 외 문맥에서는 Public Relations를 뜻할 수 있으므로 문맥으로 구분한다.'),
    ('LGTM', '검토자가 변경 내용을 승인할 만하다고 판단했다는 신호로 해석한다.', 'Looks Good To Me. 리뷰 승인 표현이지만 모든 품질과 위험을 보증한다는 의미로 단정하지 않는다.'),
    ('MVP', '제품 문맥에서는 핵심 가치를 검증할 수 있는 최소 기능 제품으로 해석한다.', 'Minimum Viable Product. 스포츠 등 다른 문맥에서는 Most Valuable Player를 뜻할 수 있다.'),
    ('스프린트', '정해진 기간 동안 선택한 작업 목표를 집중적으로 수행하는 반복 주기로 해석한다.', '애자일 및 스크럼에서 주로 사용하며 기간과 운영 규칙은 팀마다 다를 수 있다.'),
    ('백로그', '향후 수행할 기능, 개선 또는 작업 후보를 정리하고 우선순위화한 목록으로 해석한다.', 'Backlog. 제품 백로그와 스프린트 백로그처럼 범위가 다를 수 있으므로 문맥을 확인한다.'),
    ('스탠드업', '팀이 진행 상황, 다음 작업과 장애 요인을 짧게 공유하는 정기 회의로 해석한다.', 'Stand-up. 실제로 서서 진행해야 한다는 의미보다 짧고 집중된 동기화 회의를 뜻한다.'),
    ('회고', '완료한 작업 과정과 협업 방식을 돌아보고 개선할 점과 후속 행동을 정하는 활동으로 해석한다.', 'Retrospective. 개인 평가보다 팀의 과정 개선에 초점을 두는 것이 일반적이다.'),
    ('킥오프', '프로젝트나 업무를 공식적으로 시작하며 목표, 범위, 역할과 일정을 공유하는 회의로 해석한다.', 'Kickoff. 착수 합의 이후 변경 관리 방식과 후속 의사소통 채널도 함께 정할 수 있다.'),
    ('마일스톤', '프로젝트 진행을 판단하기 위한 주요 단계나 핵심 완료 지점으로 해석한다.', 'Milestone. 중요한 확인 지점이지만 항상 최종 마감일과 같은 의미는 아니다.');
